using DSAExperimentation.Benchmarks.Fixtures;

namespace DSAExperimentation.Benchmarks.Tests.Fixtures;

// Harness coverage for StackSequenceWorkloads (ARCHITECTURE 17.7). LC 946's reading depends on the
// pop order being genuinely legal for the pushed order: generated by simulating real pushes and
// pops means the exhaustive backtracking arm is forced through a real search, where a random
// permutation would mostly fail on an early mismatch and measure only the rejection path.
public sealed partial class StackSequenceWorkloadsTests
{
    private const int Length = 16;
    private const int Seed = 946; // LC problem number
    private const int FirstValue = 0;

    [Fact]
    public void BuildPushed_Length_ReturnsTheValuesZeroThroughLengthMinusOne() =>
        Assert.Equal(Enumerable.Range(FirstValue, Length), StackSequenceWorkloads.BuildPushed(Length));

    [Fact]
    public void BuildValidPopOrder_Pushed_ReturnsEveryPushedValueExactlyOnce() =>
        Assert.Equal(
            StackSequenceWorkloads.BuildPushed(Length).Order(),
            StackSequenceWorkloads.BuildValidPopOrder(StackSequenceWorkloads.BuildPushed(Length), Seed).Order());

    [Fact]
    public void BuildValidPopOrder_Pushed_ReturnsAStackLegalOrder() =>
        Assert.True(
            IsStackLegal(
                StackSequenceWorkloads.BuildPushed(Length),
                StackSequenceWorkloads.BuildValidPopOrder(StackSequenceWorkloads.BuildPushed(Length), Seed)));

    [Fact]
    public void BuildValidPopOrder_SameSeed_ReturnsTheSameOrder() =>
        Assert.Equal(
            StackSequenceWorkloads.BuildValidPopOrder(StackSequenceWorkloads.BuildPushed(Length), Seed),
            StackSequenceWorkloads.BuildValidPopOrder(StackSequenceWorkloads.BuildPushed(Length), Seed));

    // The definition of a legal pop order for a push sequence, derived here rather than taken from
    // either benchmark arm: replay the pops greedily, pushing until the next popped value is on top.
    private static bool IsStackLegal(int[] pushed, int[] popped)
    {
        var stack = new Stack<int>();
        var pushIndex = 0;

        foreach (var value in popped)
        {
            while (stack.Count == 0 || stack.Peek() != value)
            {
                if (pushIndex == pushed.Length)
                {
                    return false;
                }

                stack.Push(pushed[pushIndex]);
                pushIndex++;
            }

            stack.Pop();
        }

        return stack.Count == 0;
    }
}
